     1→// 🐀 Test Mouse: INTERRUPT STORM
     2→// 목표: 하드웨어 인터럽트 폭풍에서 커널의 견고성 검증
     3→// 무관용 규칙:
     4→//   1. Data Corruption = 0 (단 1비트도 손상되면 DEAD)
     5→//   2. Context Switch Latency < 100μs (무한 대기 금지)
     6→//   3. Kernel Panic = 0 (어떤 상황에서도 죽으면 DEAD)
     7→
     8→#[cfg(test)]
     9→mod tests {
    10→    use std::sync::{Arc, Mutex};
    11→    use std::sync::atomic::{AtomicU64, Ordering};
    12→    use std::time::Instant;
    13→
    14→    struct InterruptStormMouse {
    15→        interrupt_count: Arc<AtomicU64>,
    16→        data_corruption_detected: Arc<Mutex<bool>>,
    17→        total_latency_us: Arc<Mutex<u64>>,
    18→        panic_count: Arc<Mutex<u32>>,
    19→    }
    20→
    21→    impl InterruptStormMouse {
    22→        fn new() -> Self {
    23→            Self {
    24→                interrupt_count: Arc::new(AtomicU64::new(0)),
    25→                data_corruption_detected: Arc::new(Mutex::new(false)),
    26→                total_latency_us: Arc::new(Mutex::new(0)),
    27→                panic_count: Arc::new(Mutex::new(0)),
    28→            }
    29→        }
    30→
    31→        // Phase 1: 정상 인터럽트 기준선 측정
    32→        fn measure_baseline_interrupt_rate(&self) -> u64 {
    33→            println!("🐀 [INTERRUPT STORM] Phase 1: Measuring baseline interrupt rate...");
    34→
    35→            // 시뮬레이션: 정상 상태 = 초당 1,000 인터럽트
    36→            let baseline_rate = 1000;
    37→            println!("✅ Baseline: {} interrupts/sec", baseline_rate);
    38→
    39→            baseline_rate
    40→        }
    41→
    42→        // Phase 2: 인터럽트 폭풍 생성 (초당 100,000 이상)
    43→        fn trigger_interrupt_storm(&self, duration_secs: u64) {
    44→            println!("🐀 [INTERRUPT STORM] Phase 2: Triggering interrupt storm...");
    45→            println!("  Duration: {}s", duration_secs);
    46→            println!("  Target Rate: 100,000 interrupts/sec (100x baseline)");
    47→
    48→            let start = Instant::now();
    49→            let mut last_count = 0u64;
    50→
    51→            while start.elapsed().as_secs() < duration_secs {
    52→                // 인터럽트 증가
    53→                let current_count = self.interrupt_count.fetch_add(1000, Ordering::Relaxed);
    54→
    55→                // 매초 속도 보고
    56→                if current_count - last_count >= 100000 {
    57→                    let elapsed_ms = start.elapsed().as_millis();
    58→                    let rate = (current_count as u128 * 1000) / (elapsed_ms + 1);
    59→                    println!("  📊 Rate: {} interrupts/sec", rate);
    60→                    last_count = current_count;
    61→                }
    62→            }
    63→
    64→            println!("✅ Storm duration complete");
    65→        }
    66→
    67→        // Phase 3: 무관용 데이터 일관성 검증 (1비트도 손상되면 DEAD)
    68→        fn verify_data_integrity(&self) -> bool {
    69→            println!("🐀 [INTERRUPT STORM] Phase 3: Verifying data integrity...");
    70→
    71→            // 시뮬레이션: 메모리 영역 체크섬
    72→            let mut checksum = 0u64;
    73→            for i in 0..1000 {
    74→                checksum ^= (i * 0x9e3779b97f4a7c15u64); // 일관된 계산
    75→            }
    76→
    77→            // 다시 계산해서 비교
    78→            let mut checksum2 = 0u64;
    79→            for i in 0..1000 {
    80→                checksum2 ^= (i * 0x9e3779b97f4a7c15u64);
    81→            }
    82→
    83→            if checksum != checksum2 {
    84→                println!("❌ [DEAD] Data corruption detected: {} != {}", checksum, checksum2);
    85→                *self.data_corruption_detected.lock().unwrap() = true;
    86→                return false;
    87→            }
    88→
    89→            println!("✅ Data integrity maintained (checksum: 0x{:x})", checksum);
    90→            true
    91→        }
    92→
    93→        // Phase 4: Context Switch 지연시간 검증 (무관용 규칙: < 100μs)
    94→        fn measure_context_switch_latency(&self, samples: u32) {
    95→            println!("🐀 [INTERRUPT STORM] Phase 4: Measuring context switch latency...");
    96→
    97→            let mut total_latency_us = 0u64;
    98→
    99→            for _ in 0..samples {
   100→                let start = Instant::now();
   101→
   102→                // 시뮬레이션: context switch
   103→                std::thread::yield_now();
   104→
   105→                let elapsed_us = start.elapsed().as_micros() as u64;
   106→                total_latency_us += elapsed_us;
   107→
   108→                // 무관용 규칙: 100μs 초과 = 실패
   109→                if elapsed_us > 100 {
   110→                    println!("❌ [DEAD] Context switch latency exceeded 100μs: {}μs", elapsed_us);
   111→                    return;
   112→                }
   113→            }
   114→
   115→            let avg_latency = total_latency_us / samples as u64;
   116→            println!("✅ Context switch latency OK: avg={}μs (threshold: 100μs)", avg_latency);
   117→            *self.total_latency_us.lock().unwrap() = total_latency_us;
   118→        }
   119→
   120→        // Phase 5: 최종 무관용 검증
   121→        fn final_unforgiving_verification(&self) -> bool {
   122→            println!("🐀 [INTERRUPT STORM] Phase 5: Final unforgiving verification...");
   123→
   124→            // 규칙 1: 데이터 손상 = 0
   125→            if *self.data_corruption_detected.lock().unwrap() {
   126→                println!("❌ [DEAD] Data corruption detected. System BROKEN.");
   127→                return false;
   128→            }
   129→            println!("✅ Data corruption = 0");
   130→
   131→            // 규칙 2: Panic 발생 = 0
   132→            let panic_count = *self.panic_count.lock().unwrap();
   133→            if panic_count > 0 {
   134→                println!("❌ [DEAD] Kernel panics detected: {}. System UNSTABLE.", panic_count);
   135→                return false;
   136→            }
   137→            println!("✅ Kernel panics = 0");
   138→
   139→            // 규칙 3: 인터럽트 처리됨
   140→            let interrupt_count = self.interrupt_count.load(Ordering::Relaxed);
   141→            if interrupt_count == 0 {
   142→                println!("❌ [DEAD] No interrupts processed. System BROKEN.");
   143→                return false;
   144→            }
   145→            println!("✅ Interrupts processed: {}", interrupt_count);
   146→
   147→            true
   148→        }
   149→    }
