    16→  function transpileFile(filename: string): { success: boolean; code: string; errors: string[] } {
    17→    try {
    18→      const filePath = path.join(examplesDir, filename);
    19→      if (!fs.existsSync(filePath)) {
    20→        return {
    21→          success: false,
    22→          code: "",
    23→          errors: [`File not found: ${filePath}`],
    24→        };
    25→      }
    26→
    27→      const sourceCode = fs.readFileSync(filePath, "utf-8");
    28→
    29→      // Lexing
    30→      const lexer = new Lexer(sourceCode);
    31→      const lexResult = lexer.tokenize();
    32→
    33→      // Parsing
    34→      const parser = new Parser(lexResult.tokens);
    35→      const parseResult = parser.parse();
    36→
    37→      // Code Generation
    38→      const codegen = new ZLangCodeGen();
    39→      const zlangCode = codegen.generate(parseResult.program);
    40→
    41→      return {
    42→        success: true,
    43→        code: zlangCode,
    44→        errors: parseResult.errors.map((e: any) => `${e.line}:${e.col}: ${e.message}`),
    45→      };
    46→    } catch (error) {
    47→      return {
    48→        success: false,
    49→        code: "",
    50→        errors: [(error as Error).message],
    51→      };
    52→    }
    53→  }
    54→
    55→  function validateZLangSyntax(code: string): boolean {
    56→    // Basic Z-Lang syntax validation
    57→    const hasMain = /fn\s+main\s*\(/.test(code);
    58→    const hasMatchingBraces =
    59→      (code.match(/\{/g) || []).length === (code.match(/\}/g) || []).length;
    60→
    61→    return hasMain && hasMatchingBraces;
    62→  }
