     1→/**
     2→ * FreeLang → Z-Lang Transpiler (Phase 2 Enhanced)
     3→ *
     4→ * AST를 받아서 Z-Lang 소스 코드 문자열로 변환
     5→ */
     6→
     7→export class ZLangCodeGen {
     8→  private indentLevel: number = 0;
     9→
    10→  private indent(): string {
    11→    return "  ".repeat(this.indentLevel);
    12→  }
    13→
    14→  /**
    15→   * 프로그램 전체 변환
    16→   */
    17→  generate(ast: any): string {
    18→    if (!ast || !ast.stmts) {
    19→      return "";
    20→    }
    21→
    22→    const statements = ast.stmts
    23→      .map((stmt: any) => this.genStmt(stmt))
    24→      .filter((s: string) => s.length > 0)
    25→      .join("\n");
    26→
    27→    return statements;
    28→  }
    29→
    30→  /**
    31→   * 문(Statement) 변환
    32→   */
    33→  private genStmt(stmt: any): string {
    34→    if (!stmt) return "";
    35→
    36→    switch (stmt.kind) {
    37→      case "var_decl":
    38→        return this.genVarDecl(stmt);
    39→      case "fn_decl":
    40→        return this.genFunction(stmt);
    41→      case "if_stmt":
    42→        return this.genIf(stmt);
    43→      case "for_stmt":
    44→        return this.genForIn(stmt);
    45→      case "return_stmt":
    46→        return this.genReturn(stmt);
    47→      case "expr_stmt":
    48→        return this.genExprStmt(stmt);
    49→      case "spawn_stmt":
    50→        return this.genSpawn(stmt);
    51→      case "match_stmt":
    52→        return this.genMatch(stmt);
    53→      default:
    54→        return `${this.indent()}// TODO: ${stmt.kind}`;
    55→    }
    56→  }
    57→
    58→  /**
    59→   * 변수 선언
    60→   */
    61→  private genVarDecl(stmt: any): string {
    62→    const name = stmt.name;
    63→    const type = this.convertType(stmt.type);
    64→    const init = this.genExpr(stmt.init);
    65→    return `${this.indent()}let ${name}: ${type} = ${init};`;
    66→  }
    67→
    68→  /**
    69→   * 함수 정의
    70→   */
    71→  private genFunction(stmt: any): string {
    72→    const name = stmt.name;
    73→    const params = stmt.params
    74→      .map((p: any) => `${p.name}: ${this.convertType(p.type)}`)
    75→      .join(", ");
    76→
    77→    const returnType = stmt.returnType ? ` -> ${this.convertType(stmt.returnType)}` : "";
    78→    const body = this.genBlock(stmt.body, stmt.returnType);
    79→    return `${this.indent()}fn ${name}(${params})${returnType} {\n${body}\n${this.indent()}}`;
    80→  }

